    "practiceSolution": "class Person:\n    def __init__(self, name: str):\n        self.name = name\n\nclass Employee(Person):\n    def __init__(self, name: str, salary: float):\n        super().__init__(name)\n        self.salary = salary\n\nemp = Employee(\"John\", 85000.0)\nprint(f\"{emp.name}: ${emp.salary}\")",
